                return false;
            }
            String host = url.getHost().toLowerCase();
            // Remove brackets for IPv6
            String cleanHost = host.replace("[", "").replace("]", "");

            if (BLOCKED_HOSTS.contains(host) || BLOCKED_HOSTS.contains(cleanHost)) {
                return false;
